// MANUAL FILE (not generated by HARIA). Safe across regenerations.
//
// Implements the AddTrustedClaims extension point that HARIA declares in
// HariaWebAuthentication.cs (a generated file, do not edit it). HARIA calls it on
// every sign-in (Login and Register) with the entity loaded by the server,
// after the credentials have been checked.
//
// Here the backend Usuario (with RolUsuario) is translated into the web
// inheritance hierarchy, and its roles are written into the auth cookie. That
// is what makes [Authorize(Roles = ...)] work.
using System.Security.Claims;
using WikiGames.Domain.Entities;
using WikiGames.Web.Models.Usuarios;

namespace WikiGames.Web.Utils.Security;

public static partial class HariaWebAuthentication
{
    static partial void AddTrustedClaims(List<Claim> claims, string domainClass, object identifier, object? serverEntity)
    {
        // Only use the server-loaded entity. Never trust the form or the session snapshot.
        if (serverEntity is not Usuario usuario) return;

        var model = UsuarioModelMapper.FromEntity(usuario);

        claims.Add(new Claim(UsuarioClaimTypes.UserSubclass, model.UserClass));
        claims.Add(new Claim(ClaimTypes.GivenName, model.Name));
        claims.Add(new Claim(ClaimTypes.Email, model.Email));

        foreach (var role in model.Roles)
        {
            // RolesByUserClass in appsettings.Haria.json may already have added the same role.
            if (!claims.Any(c => c.Type == ClaimTypes.Role && c.Value == role))
                claims.Add(new Claim(ClaimTypes.Role, role));
        }
    }
}
